css/styles.css:
:root {
  color-scheme: dark;
  --background: #0b0b0e;
  --foreground: #f2f1f3;
  --muted: #bab7c1;
  --subtle: #a4a0ad;
  --line: rgba(233, 231, 240, .14);
  --heading-font: "Manrope", "Segoe UI", Arial, sans-serif;
  --body-font: "Inter", "Segoe UI", Arial, sans-serif;
  --gutter: clamp(24px, 4.2vw, 80px);
  --header-height: 92px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: calc(var(--header-height) + 24px); }
body { margin: 0; background: var(--background); color: var(--foreground); font: 400 18px/1.6 var(--body-font); -webkit-font-smoothing: antialiased; }
main { background: var(--background); }
a { color: inherit; text-decoration: none; }
button, summary { font: inherit; }
a, summary { -webkit-tap-highlight-color: transparent; }
img { display: block; max-width: 100%; }
figure, p, h1, h2, h3 { margin: 0; }
h2, h3 { font-family: var(--heading-font); font-weight: 600; letter-spacing: -.055em; line-height: 1.12; }
h2 { font-size: clamp(44px, 5.3vw, 88px); }
h3 { font-size: clamp(40px, 4.5vw, 72px); }
::selection { background: #dad7df; color: #131217; }
:focus-visible { outline: 2px solid var(--foreground); outline-offset: 6px; }
[hidden] { display: none !important; }
.container { width: min(calc(100% - var(--gutter) * 2), 1600px); margin-inline: auto; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
.skip-link { position: fixed; top: 12px; left: var(--gutter); z-index: 100; padding: 12px 20px; background: var(--foreground); color: var(--background); transform: translateY(-180%); }
.skip-link:focus { transform: none; }

.site-header { position: sticky; top: 0; z-index: 20; height: var(--header-height); border-bottom: 1px solid var(--line); background: #0c0c10; }
.header-inner, .header-actions, .brand, .desktop-nav { display: flex; align-items: center; }
.header-inner { height: 100%; justify-content: space-between; gap: 28px; }
.brand { gap: 12px; min-height: 44px; }
.brand-skull { width: 30px; height: 36px; flex: none; }
.brand-word { font: 800 15px/1.2 var(--heading-font); letter-spacing: .08em; }
.brand-caption { display: block; margin-top: 5px; color: var(--subtle); font: 500 12px/1.3 var(--body-font); letter-spacing: .07em; }
.desktop-nav { gap: clamp(24px, 3vw, 48px); color: var(--muted); font-size: 15px; }
.desktop-nav a, .footer-inner a { display: inline-flex; align-items: center; min-height: 44px; transition: color .2s; }
.desktop-nav a:hover, .footer-inner a:hover { color: #fff; text-decoration: underline; text-underline-offset: 6px; }
.header-actions { gap: 16px; }
.button { display: inline-flex; align-items: center; justify-content: center; min-height: 56px; padding: 14px 25px; border: 1px solid transparent; font-size: 15px; font-weight: 600; line-height: 1.4; text-align: center; transition: background-color .2s, border-color .2s, color .2s; }
.button-primary { background: var(--foreground); color: #16151a; }
.button-primary:hover { background: #fff; border-color: #fff; }
.button-outline { border-color: #6e6a75; }
.button-outline:hover { background: var(--foreground); color: #16151a; border-color: var(--foreground); }
.header-cta { min-height: 48px; padding: 11px 20px; font-size: 14px; }
.text-link { display: inline-flex; align-items: center; min-height: 48px; padding-block: 10px; font-size: 15px; font-weight: 500; text-decoration: underline; text-decoration-color: #77717f; text-underline-offset: 7px; transition: text-decoration-color .2s, color .2s; }
.text-link:hover { color: #fff; text-decoration-color: #fff; }
.mobile-menu { display: none; }
.eyebrow, .section-label, .scene-number, .object-caption { color: var(--muted); font-size: 13px; font-weight: 500; line-height: 1.5; letter-spacing: .1em; text-transform: uppercase; }
.section-label { display: inline-flex; align-items: center; gap: 16px; }
.section-label::before { content: ""; width: 32px; height: 1px; background: #9d98a6; flex: none; }

.hero { position: relative; isolation: isolate; overflow: hidden; background: radial-gradient(ellipse 34% 48% at 66% 50%, rgba(64, 71, 82, .30), rgba(64, 71, 82, .10) 40%, rgba(64, 71, 82, 0) 100%), radial-gradient(ellipse 26% 32% at 72% 65%, rgba(40, 44, 52, .08), rgba(40, 44, 52, 0) 100%); }
.hero-layout { position: relative; z-index: 1; display: flex; align-items: center; min-height: max(720px, calc(100svh - var(--header-height))); padding-block: 70px 110px; }
.hero-copy { position: relative; z-index: 2; width: 45%; }
.hero-eyebrow { margin-bottom: 34px; letter-spacing: .075em; margin-left: 12px; }
.hero-title { width: max-content; max-width: 100%; font: 800 clamp(100px, 10.7vw, 196px)/.85 var(--heading-font); letter-spacing: -.075em; }
.hero-title-top { display: block; }
.hero-title-bottom { display: flex; align-items: flex-end; gap: .028em; margin-top: .15em; }
.diamond-glyph { width: .94em; height: .79em; flex: none; margin-left: -.016em; margin-bottom: -.008em; }
.hero-title-outline { color: transparent; -webkit-text-stroke: 1px #c7c2cd; }
.hero-summary { max-width: 400px; margin-top: 36px; color: var(--muted); font-size: 18px; line-height: 1.65; }
.hero-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 16px 26px; margin-top: 30px; }
.product-stage { position: relative; isolation: isolate; margin: 0; background: none; overflow: visible; }
.hero-art { position: absolute; z-index: 0; inset: 0; overflow: hidden; pointer-events: none; container-type: size; }
.product-image { position: relative; z-index: 1; width: 100%; height: 100%; object-fit: contain; user-select: none; }
/* Reference canvas: 1776 × 1312. Each original PNG keeps its own bounds. */
.hero-scene { position: absolute; left: 50%; top: 62%; width: max(100cqw, 135.3659cqh); height: max(100cqh, 73.8739cqw); transform: translate(-50%, -62%); }
.hero-layer { position: absolute; transform: translate3d(0, 0, 0); }
.hero-layer img { display: block; width: 100%; height: 100%; user-select: none; }
.hero-scene-image { object-fit: contain; }
.hero-layer-back-smoke { left: 0; top: -3.5823%; width: 100%; height: 103.5823%; }
.hero-layer-central { left: 18.4685%; top: 17.2256%; width: 81.5315%; height: 82.7744%; }
.hero-layer-front-smoke { left: 55.518%; top: 54.8018%; width: 44.482%; height: 45.1982%; }
.hero-layer-foreground { left: 47.2973%; top: 48.628%; width: 52.7027%; height: 51.372%; }
/* Fade only the cut canvas edges, retaining the supplied silhouette. */
.hero-smoke { mask-image: linear-gradient(90deg, transparent, #000 3%, #000 97%, transparent), linear-gradient(180deg, transparent, #000 4%, #000 95%, transparent); mask-composite: intersect; }
.hero-art[data-motion-active] .hero-layer, .hero-art[data-motion-active] .hero-smoke { will-change: transform; }
.hero-art .product-halo, .hero-art .product-shadow { display: none; }
.hero-art::after {
  content: "";
  position: absolute;
  z-index: 2;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, var(--background), rgba(11, 11, 14, .90) 22%, rgba(11, 11, 14, .80) max(30%, 440px), transparent max(48%, 600px), transparent 94%, var(--background)),
    linear-gradient(180deg, var(--background), transparent 13%, transparent 76%, var(--background));
}
.product-halo { position: absolute; z-index: -1; inset: -24% -5%; background: radial-gradient(ellipse 50% 50% at 50% 50%, rgba(175, 191, 225, .075), rgba(175, 191, 225, .03) 38%, rgba(175, 191, 225, 0) 82%); pointer-events: none; }
.product-shadow { position: absolute; z-index: -1; width: 78%; height: 16%; left: 8%; bottom: 9%; transform: rotate(-23deg); background: radial-gradient(ellipse 50% 50% at 50% 50%, rgba(0, 0, 0, .67), rgba(0, 0, 0, .25) 38%, rgba(0, 0, 0, 0) 72%); filter: blur(15px); pointer-events: none; }
.image-fallback { position: absolute; inset: 0; display: grid; align-content: center; padding: 32px; color: var(--muted); font-size: 16px; text-align: center; }
.hero-bottom { position: absolute; z-index: 2; bottom: 30px; left: 0; right: 0; display: flex; justify-content: space-between; align-items: center; gap: 20px; }
.scroll-link { min-height: 44px; }
.scroll-link:hover { color: var(--foreground); }
.object-caption { color: var(--subtle); font-size: 12px; }

.concept {
  padding-block: clamp(112px, 11vw, 190px);
  border-block: 1px solid transparent;
  background: radial-gradient(ellipse 39% 34% at 61% 52%, rgba(93, 100, 118, .28), rgba(93, 100, 118, .12) 45%, rgba(93, 100, 118, 0) 100%);
}
.concept-layout { display: grid; grid-template-columns: 1fr 2.4fr; gap: 56px; align-items: start; }
.concept-layout > .section-label { margin-top: 12px; }
.concept-copy h3 span { color: #aaa5b3; }
.concept-copy > p { max-width: 520px; margin-top: 38px; color: var(--muted); }
.details-section {
  background: radial-gradient(ellipse clamp(287.5px, 25vw, 550px) 100% at 27% 0%, rgba(93, 100, 118, .138), rgba(93, 100, 118, .046) 45%, rgba(93, 100, 118, 0) 100%) top / 100% clamp(187.5px, 15vw, 262.5px) no-repeat;
}
.details-intro { display: flex; align-items: flex-end; justify-content: space-between; gap: 48px; padding-block: 105px 65px; }
.details-intro h3 { margin-top: 28px; }
.details-intro > p { max-width: 300px; color: var(--muted); margin-bottom: 6px; font-size: 16px; }
.detail-scene { border-top: 1px solid transparent; }
.scene-layout { display: grid; grid-template-columns: .82fr 1.38fr; align-items: center; column-gap: clamp(48px, 6vw, 100px); min-height: clamp(620px, 80svh, 900px); padding-block: 64px; }
.scene-copy { min-width: 0; }
.scene-number { margin-bottom: 26px; color: var(--subtle); }
.scene-copy h3 { margin-bottom: 26px; }
.scene-copy > p:last-child { max-width: 390px; color: var(--muted); }
.scene-art { aspect-ratio: 1.22; min-width: 0; }
.scene-art figcaption { position: absolute; z-index: 2; left: 0; bottom: 0; padding: 18px 0; color: var(--subtle); font-size: 13px; letter-spacing: .065em; }
.scene-silhouette {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: radial-gradient(ellipse 32% 48% at 66% 50%, rgba(93, 100, 118, .16), rgba(93, 100, 118, 0) 100%);
}
.scene-silhouette .scene-layout { position: relative; z-index: 1; display: flex; align-items: flex-start; min-height: clamp(760px, 62.5vw, 1100px); padding-block: clamp(108px, 9vw, 172px) 160px; }
.scene-silhouette .scene-copy { width: 32%; }
.scene-silhouette .scene-copy > p:last-child { max-width: 320px; }
.silhouette-art { position: absolute; z-index: 0; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.silhouette-image { width: 85%; height: 100%; margin-left: auto; object-fit: contain; object-position: 100% 50%; mask-image: linear-gradient(180deg, transparent, #000 8%, #000 92%, transparent); }
.scene-texture {
  position: relative;
  isolation: isolate;
  background: radial-gradient(ellipse 44% 48% at 44% 50%, rgba(89, 99, 115, .15), rgba(89, 99, 115, 0) 100%);
}
.scene-texture .scene-copy { grid-column: 2; grid-row: 1; }
.scene-texture .scene-layout {
  position: relative;
  z-index: 1;
  grid-template-columns: 1.38fr .82fr;
  min-height: 62.5vw;
}
.texture-art { position: absolute; z-index: 0; inset: 0; overflow: hidden; }
.texture-art picture { display: block; }
.texture-placeholder { display: block; width: 100%; height: auto; user-select: none; }
.texture-art::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, var(--background), transparent 7%, transparent 88%, var(--background)),
    linear-gradient(180deg, var(--background), transparent 13%, transparent 80%, var(--background));
}
/* Registered transparent layers share the same framing. */
.scene-impact {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--background);
}
.impact-art {
  position: absolute;
  z-index: 0;
  inset: 0;
  overflow: hidden;
}
.impact-art::after {
  content: "";
  position: absolute;
  z-index: 3;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, var(--background), transparent 14%, transparent 88%, var(--background)),
    linear-gradient(180deg, var(--background), transparent 13%, transparent 76%, var(--background));
}
.impact-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
  user-select: none;
}
.impact-layer-group { position: relative; width: 100%; height: 100%; }
.impact-head { position: absolute; inset: 0; z-index: 1; }
.impact-head-broken { visibility: hidden; }
.impact-bat { position: absolute; z-index: 2; inset: 0; }
.scene-smoke { pointer-events: none; user-select: none; }
.impact-smoke {
  position: absolute;
  z-index: 0;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
  opacity: .2;
}
.impact-layout {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  min-height: clamp(760px, 62.5vw, 1100px);
  padding-block: clamp(108px, 9vw, 172px) 180px;
}
.impact-copy { width: 39%; }
.impact-copy .scene-number { margin-bottom: 32px; }
.impact-copy h3 {
  margin-bottom: 32px;
}
.impact-copy > p:last-child { max-width: 330px; font-size: 18px; line-height: 1.65; }
.impact-art .image-fallback { inset: 0 0 0 45%; }

.final-section {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background: var(--background);
  border-top: 1px solid var(--line);
}
.final-section::after {
  content: "";
  position: absolute;
  z-index: 0;
  inset: 1px 0 0;
  pointer-events: none;
  background: linear-gradient(180deg, var(--background), transparent 6%, transparent 94%, var(--background));
}
.character-layout {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: flex-end;
  align-items: flex-start;
  min-height: clamp(800px, 64vw, 1140px);
  padding-block: clamp(112px, 10vw, 170px) 96px;
}
.character-copy { min-width: 0; width: 30%; }
.character-copy .final-copy { max-width: 560px; }
.character-copy h3 { margin-top: 28px; }
.character-copy .final-copy > p:not(.section-label) { margin-top: 28px; color: var(--muted); }
.character-copy .button { margin-top: 28px; }
.character-stage {
  position: absolute;
  z-index: 0;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: min(88%, 1640px);
  aspect-ratio: 1519 / 1035;
  overflow: hidden;
  mix-blend-mode: lighten;
  mask-image:
    linear-gradient(90deg, transparent, #000 7%, #000 88%, transparent),
    linear-gradient(180deg, transparent, #000 13%, #000 80%, transparent);
  mask-composite: intersect;
  pointer-events: none;
}
.character-objects { position: absolute; z-index: 1; inset: 0; }
.character-object { position: absolute; }
.character-object img { display: block; width: 100%; height: auto; user-select: none; }
.character-bottle { z-index: 1; left: 44.4%; top: 2.5%; width: 37.5%; }
.character-glass { z-index: 2; left: 8.2%; top: 0; width: 48.7%; }
.character-bat { z-index: 3; left: -2.9%; top: 27.6%; width: 104%; }
.character-bat img { transform: rotate(29deg); }
.character-stage[data-character-moving] .character-object { will-change: transform, opacity; }
.character-smoke { position: absolute; z-index: 0; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: .28; }
.site-footer { border-top: 1px solid transparent; background: var(--background); }
.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 28px; min-height: 102px; color: var(--subtle); font-size: 13px; }
.footer-brand { color: var(--foreground); font: 800 14px/1.4 var(--heading-font); letter-spacing: .09em; }
.footer-inner nav { display: flex; gap: 32px; color: var(--muted); }

.concept, .details-section, .site-footer,
.detail-scene.scene-silhouette, .detail-scene.scene-impact, .detail-scene.scene-texture {
  border-top: 1px solid var(--line);
}

@media (max-width: 1100px) {
  .character-layout { padding-block: 96px; }
  .character-copy { width: 32%; }
  .character-stage { width: 80%; }
  .hero-layout { min-height: auto; padding-bottom: 24px; }
  .hero-copy { width: 100%; }
  .hero-title { font-size: 10.4vw; }
  .hero-summary { max-width: 350px; font-size: 17px; }
  .hero-actions { align-items: flex-start; flex-direction: column; gap: 10px; }
  .hero-art { position: relative; inset: auto; width: 100%; aspect-ratio: 16 / 9; margin-top: -24px; margin-bottom: 70px; mask-image: linear-gradient(180deg, transparent, #000 12%, #000 80%, transparent); }
  .hero-scene { top: 56%; transform: translate(-50%, -56%); }
  .hero-art::after { background: none; }
  .concept-layout { grid-template-columns: 1fr 2.6fr; gap: 30px; }
  .scene-layout { column-gap: 40px; }
  .scene-copy > p:last-child { font-size: 17px; }
  .scene-silhouette .scene-layout { display: block; min-height: auto; padding-block: 64px 24px; }
  .scene-silhouette .scene-copy { width: 100%; }
  .scene-silhouette .scene-copy > p:last-child { max-width: 480px; }
  .silhouette-art { position: relative; inset: auto; height: auto; aspect-ratio: 16 / 9; margin-top: -24px; margin-bottom: 64px; }
  .impact-layout { min-height: auto; padding-block: 72px 24px; }
  .impact-copy { width: 100%; }
  .impact-copy > p:last-child { max-width: 380px; }
  .impact-art { position: relative; aspect-ratio: 3 / 2; margin-top: -30px; }
  .impact-layout { order: 0; }
  .scene-impact { display: flex; flex-direction: column; padding-bottom: 24px; }
  .impact-art { order: 1; }
  .impact-image { object-fit: contain; }
  .impact-smoke { object-fit: contain; }
  .impact-art::after {
    background: linear-gradient(180deg, var(--background), transparent 12%, transparent 78%, var(--background));
  }
  .impact-art .image-fallback { inset: 0; }
}

@media (max-width: 850px) {
  .final-section { display: flex; flex-direction: column; }
  .final-section::after { display: none; }
  .character-layout { order: 1; min-height: auto; padding-block: 24px 64px; }
  .character-copy { width: 100%; }
  .character-stage {
    position: relative; top: auto; transform: none; width: 100%; margin-top: 32px;
    mask-image:
      linear-gradient(90deg, transparent, #000 8%, #000 87%, transparent),
      linear-gradient(180deg, transparent, #000 15%, #000 81%, transparent);
  }
  :root { --header-height: 80px; }
  .desktop-nav { display: none; }
  .mobile-menu { position: relative; display: block; font-size: 14px; }
  .mobile-menu summary { display: flex; align-items: center; justify-content: center; min-width: 56px; min-height: 48px; list-style: none; cursor: pointer; }
  .mobile-menu summary::-webkit-details-marker { display: none; }
  .mobile-menu[open] summary { color: #fff; text-decoration: underline; text-underline-offset: 6px; }
  .mobile-nav { position: absolute; top: calc(100% + 18px); right: 0; display: flex; flex-direction: column; width: min(320px, calc(100vw - var(--gutter) * 2)); padding: 12px 20px; border: 1px solid #625c6c; background: #151319; box-shadow: 0 20px 50px #0006; }
  .mobile-nav a { display: flex; align-items: center; min-height: 52px; font-size: 16px; }
  .mobile-nav a:hover { text-decoration: underline; text-underline-offset: 6px; }
  .hero-layout { display: grid; grid-template-columns: 1fr; min-height: auto; padding-block: 64px 24px; }
  .hero-copy { width: 100%; }
  .hero-title { font-size: clamp(110px, 18vw, 150px); }
  .hero-summary { max-width: 440px; }
  .hero-actions { flex-direction: row; align-items: center; gap: 14px 24px; }
  .hero-art { aspect-ratio: 4 / 3; }
  .hero-bottom { bottom: 18px; }
  .concept { background: radial-gradient(ellipse 64% 36% at 50% 56%, rgba(93, 100, 118, .28), rgba(93, 100, 118, .12) 45%, rgba(93, 100, 118, 0) 100%); }
  .concept-layout { grid-template-columns: 1fr; gap: 30px; }
  .concept-layout > .section-label { margin-top: 0; }
  .concept-copy h3 { max-width: 680px; }
  .details-intro { padding-block: 80px 52px; gap: 30px; }
  .details-intro > p { max-width: 220px; }
  .scene-layout, .scene-texture .scene-layout { min-height: auto; grid-template-columns: 1fr; gap: 28px; padding-block: 64px; }
  .scene-copy > p:last-child { max-width: 480px; font-size: 18px; }
  .scene-texture .scene-copy, .scene-texture .scene-art { grid-column: auto; grid-row: auto; }
  .scene-texture { padding-bottom: 64px; }
  .scene-texture .scene-layout { padding-bottom: 28px; }
  .texture-art { position: relative; inset: auto; width: 100%; }
  .texture-art::after {
    background:
      linear-gradient(90deg, var(--background), transparent 8%, transparent 87%, var(--background)),
      linear-gradient(180deg, var(--background), transparent 15%, transparent 81%, var(--background));
  }
  .scene-art, .scene-texture .scene-art { width: 100%; aspect-ratio: 1.45; }
  .scene-number { margin-bottom: 18px; }
  .scene-copy h3 { margin-bottom: 20px; }
  .footer-inner { flex-wrap: wrap; padding-block: 28px; gap: 16px 30px; }
  .footer-description { flex-basis: 100%; order: 3; }
}

@media (max-width: 620px) {
  .character-stage { aspect-ratio: 1122 / 1402; }
  .character-bottle { left: 48.2%; top: 7.5%; width: 49%; }
  .character-glass { left: 0; top: 7%; width: 73%; }
  .character-bat { left: -18.3%; top: 33.7%; width: 134.6%; }
  .character-bat img { transform: rotate(51deg); }
}

@media (max-width: 520px) {
  .character-layout { padding-block: 12px 48px; }
  .character-stage { margin-top: 24px; }
  .character-copy h3,
  .character-copy .final-copy > p:not(.section-label),
  .character-copy .button { margin-top: 24px; }
  :root { --gutter: 22px; --header-height: 76px; }
  body { font-size: 16px; }
  h2 { font-size: clamp(38px, 10.4vw, 54px); }
  h3 { font-size: clamp(36px, 10vw, 48px); }
  .header-inner { gap: 12px; }
  .brand { gap: 8px; }
  .brand-skull { width: 23px; height: 29px; }
  .brand-word { font-size: 12px; letter-spacing: .06em; }
  .brand-caption { font-size: 12px; letter-spacing: 0; }
  .header-actions { gap: 10px; }
  .header-cta { font-size: 14px; padding: 10px; min-height: 44px; }
