/* Shared registration frame; all assets keep their native proportions. */
.impact-layer-group[data-registered] {
  position: absolute;
  width: var(--impact-width);
  height: var(--impact-height);
  left: var(--impact-left);
  top: var(--impact-top);
}
/* Keep the contact at 24% of the shared frame without stretching the head. */
.impact-layer-group .impact-head {
  top: 3.75%;
  bottom: auto;
  height: auto;
  aspect-ratio: 16 / 9;
  object-fit: contain;
  -webkit-mask-image: linear-gradient(#000 88%, transparent);
  mask-image: linear-gradient(#000 88%, transparent);
}
.impact-smoke-front { z-index: 0; opacity: .14; }
.impact-flash {
  position: absolute;
  z-index: 4;
  left: 70%; top: 24%;
  width: 17%; height: 24%;
  transform: translate(-50%, -50%);
  background: radial-gradient(ellipse, #fff 0%, #e5efffcc 12%, #dbe8ff44 35%, transparent 70%);
  opacity: 0;
  pointer-events: none;
}

/* Live reconstruction of the existing texture placeholder, using its exact frame. */
.texture-layers {
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  aspect-ratio: 8 / 5;
  background: var(--background);
  pointer-events: none;
}
.texture-atmosphere-frame {
  position: absolute;
  left: 0;
  top: 50%;
  width: 111.052072%;
  aspect-ratio: 1672 / 941;
  transform: translateY(-50%);
}
.texture-smoke { position: absolute; inset: 0; width: 100%; height: 100%; opacity: .28; }
.texture-diamond {
  position: absolute;
  left: calc(var(--x) / 1672 * 100%);
  top: calc(var(--y) / 941 * 100%);
  width: calc(var(--w) / 1672 * 100%);
  height: calc(var(--h) / 941 * 100%);
  opacity: .8;
}
.texture-bat {
  position: absolute;
  left: -8%; top: 0;
  width: 98%; height: auto; max-width: none;
  transform: rotate(-15deg);
  transform-origin: 55% 50%;
}
.texture-art[data-texture-ready] picture { visibility: hidden; }
@media (max-width: 850px) {
  .texture-layers { aspect-ratio: 390 / 523; }
  .texture-atmosphere-frame { width: 238.277882%; }
  .texture-bat { left: -30%; top: 13%; width: 162%; }
}

